--
-- Table structure for table `jxxj_draw_order`
--

DROP TABLE IF EXISTS `jxxj_draw_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jxxj_draw_order` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_num` varchar(255) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `status` tinyint(1) DEFAULT '1',
  `status2` tinyint(1) DEFAULT '0',
  `huobi` varchar(255) DEFAULT NULL,
  `money` decimal(20,6) DEFAULT '0.000000' COMMENT '提现金额',
  `zuihou_value` decimal(20,6) DEFAULT '0.000000' COMMENT '提现金额的等值usdt',
  `shouxvfei_rate` decimal(5,2) DEFAULT NULL COMMENT '手续费率',
  `shouxvfei` decimal(20,6) DEFAULT '0.000000' COMMENT '手续费',
  `zuihou_shouxvfei` decimal(20,6) DEFAULT '0.000000' COMMENT '手续费的等值usdt',
  `daozhang` decimal(20,6) DEFAULT '0.000000' COMMENT '实际到账金额',
  `zuihou_daozhang` decimal(20,6) DEFAULT '0.000000' COMMENT '实际到账的等值usdt',
  `huilv_now` decimal(20,6) DEFAULT NULL,
  `to_address` varchar(255) DEFAULT NULL,
  `add_time` datetime DEFAULT NULL,
  `shenhe_user_id` int(10) DEFAULT NULL,
  `shenhe_time` datetime DEFAULT NULL,
  `tranfer_detail` varchar(1000) DEFAULT NULL,
  `hash` varchar(255) DEFAULT NULL,
  `zhuanzhang_type` tinyint(1) DEFAULT '1' COMMENT '1-自动，2-审核后自动，3-必须手动',
  PRIMARY KEY (`id`),
  KEY `uid` (`user_id`),
  KEY `idx_status_zhuanzhang_type` (`status`,`zhuanzhang_type`),
  KEY `idx_huobi` (`huobi`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

