DROP TABLE IF EXISTS `jxxj_tronkey`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jxxj_tronkey` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tronkey` char(50) NOT NULL COMMENT 'tron密钥',
  `scankey` varchar(50) NOT NULL COMMENT 'sacnkey',
  `today_tron` int(11) NOT NULL DEFAULT '0' COMMENT 'tron今天调用次数',
  `sum_tron` int(11) NOT NULL DEFAULT '0' COMMENT 'tron总调用',
  `today_scan` int(11) NOT NULL DEFAULT '0',
  `sum_scan` int(11) NOT NULL DEFAULT '0',
  `day` int(11) NOT NULL DEFAULT '0',
  `email` varchar(50) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `a` (`tronkey`),
  UNIQUE KEY `scankey` (`scankey`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8 COMMENT='配置表';
