--
-- Table structure for table `jxxj_user`
--

DROP TABLE IF EXISTS `jxxj_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jxxj_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(255) DEFAULT NULL,
  `login_pwd` varchar(255) DEFAULT NULL,
  `anquan_pwd` varchar(255) DEFAULT NULL,
  `salt` varchar(255) DEFAULT NULL,
  `telegram` varchar(255) DEFAULT '',
  `whatsapp` varchar(255) DEFAULT '',
  `from_who` int(255) DEFAULT '0',
  `erji_from` int(11) DEFAULT '0',
  `sanji_from` int(11) DEFAULT '0',
  `yiji_count` int(10) DEFAULT '0',
  `erji_count` int(10) DEFAULT '0',
  `sanji_count` int(10) DEFAULT '0',
  `country_code` varchar(255) DEFAULT NULL COMMENT '手机号前缀',
  `tel` varchar(255) DEFAULT NULL,
  `basic_balance` decimal(20,6) DEFAULT '0.000000',
  `licai_balance` decimal(20,6) DEFAULT '0.000000' COMMENT '理财账户',
  `commission_balance` decimal(20,6) DEFAULT '0.000000',
  `invite_code` varchar(255) DEFAULT NULL,
  `status` tinyint(1) DEFAULT '1',
  `wrong_time` int(2) DEFAULT '0',
  `add_time` datetime DEFAULT NULL,
  `token` varchar(255) DEFAULT '',
  `vip_level` tinyint(1) DEFAULT '0',
  `xfje` decimal(20,6) DEFAULT '0.000000' COMMENT '充值金额',
  `txje` decimal(20,6) DEFAULT '0.000000',
  `lang` varchar(255) DEFAULT NULL,
  `guojia` varchar(255) DEFAULT NULL,
  `zhuce_ip` varchar(255) DEFAULT NULL,
  `laiyuan` int(11) DEFAULT '0' COMMENT '来源用户',
  `last_login_time` datetime DEFAULT NULL COMMENT ' ',
  `can_draw` tinyint(1) DEFAULT '1' COMMENT '是否能提现',
  `tmp_task` int(2) NOT NULL DEFAULT '-1' COMMENT '限制需要升级才能有任务(-1为不限制)',
  `zyue` decimal(20,6) DEFAULT '0.000000' COMMENT '后台手动增加基础余额的额度',
  `beizhu` varchar(255) DEFAULT NULL COMMENT '备注',
  `xingbiao` tinyint(1) NOT NULL DEFAULT '0' COMMENT '星标',
  `can_wakuang` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否有挖矿收益',
  `fxz` int(8) NOT NULL DEFAULT '0',
  `daili` tinyint(1) DEFAULT '0',
  `kabuzhou` int(11) DEFAULT '0' COMMENT ' ',
  `buchong` decimal(20,6) DEFAULT '0.000000',
  `busuhi` decimal(20,6) DEFAULT '0.000000',
  `buchong2` decimal(20,6) DEFAULT '0.000000',
  PRIMARY KEY (`id`),
  UNIQUE KEY `aab` (`email`,`tel`),
  KEY `idx_from_who` (`from_who`),
  KEY `idx_erji_from` (`erji_from`),
  KEY `idx_sanji_from` (`sanji_from`),
  KEY `idx_id` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

