DROP TABLE IF EXISTS `jxxj_user_licai`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `jxxj_user_licai` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_num` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `licai_id` int(11) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `add_time` datetime DEFAULT NULL,
  `money` decimal(10,2) DEFAULT '0.00',
  `daoqi_time` datetime DEFAULT NULL,
  `day` int(3) DEFAULT NULL,
  `rate_day` float(5,2) DEFAULT '1.00',
  `shouyi_type` tinyint(1) DEFAULT '1',
  `zonglirun` decimal(10,2) DEFAULT '0.00',
  `status` tinyint(1) DEFAULT '1' COMMENT '1-未结束，2-结束',
  PRIMARY KEY (`id`),
  KEY `userid` (`user_id`),
  KEY `liciaid` (`licai_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

