  `user_id` int(11) DEFAULT NULL,
  `user_licai_id` int(11) DEFAULT NULL,
  `issue` int(11) DEFAULT '1',
  `lixi` decimal(10,2) DEFAULT NULL,
  `benjin` decimal(10,2) DEFAULT NULL,
  `daoqi_time` datetime DEFAULT NULL,
  `status` tinyint(1) DEFAULT '1' COMMENT '1-未结算，2-已结算，3-已领取',
  PRIMARY KEY (`id`),
  KEY `uid` (`user_id`),
  KEY `licaiid` (`user_licai_id`),
  KEY `idx_issue_user_licai_id_status` (`issue`,`user_licai_id`,`status`)
